}
const [SCREEN, OUT, Q = '', SECS = '6', START = '0'] = process.argv.slice(2);
const fps = 24;
const nFrames = Math.round(Number(SECS) * fps);
mkdirSync(`${OUT}/f`, { recursive: true });
